with target as(select * from public.works where id=any(array[]::bigint[]) or open_library_id=any(array['OL812141W','OL812169W','OL812178W','OL812182W','OL812212W','OL846589W','OL8970682W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['degrenslijnenuitgewist','kindtussenviervrouwen','nagelatengedichten','briefwisseling','verzameldeverhalen','lapaloma','vertoogoverdeongelijkheid','discourssurlorigineetlesfondementsdelinegaliteparmileshommes','discourseoninequality','adiscourseupontheoriginandfoundationoftheinequalityamongmankind']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['degrenslijnenuitgewist','kindtussenviervrouwen','nagelatengedichten','briefwisseling','verzameldeverhalen','lapaloma','vertoogoverdeongelijkheid','discourssurlorigineetlesfondementsdelinegaliteparmileshommes','discourseoninequality','adiscourseupontheoriginandfoundationoftheinequalityamongmankind']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL68474A','OL123631A','OL73094A','OL29048A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['simonvestdijk','svestdijk','theundevries','louisferron','jeanjacquesrousseau','rousseau','jrousseau']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL2989123M','OL5378346M','OL2429225M','OL2653920M','OL4825670M','OL9087047M','OL12808129M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789023460848','9789023460251','9789023446330','9789021485263','9789023460299','9789023409977','9789053527979']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
